NativeSignal sys0_probe_directory(VM& vm, Thread& thread) {
    const uint32_t address = thread.stack.pop();
    if (address == 0) {
        thread.stack.push(0);
        return NativeSignal::Continue;
    }
    const std::string text =
        vm.memory().read_cstring(address, thread.base);
    const auto path = resolve_host_path(vm, text);
    std::error_code error;
    const bool directory = host_files::is_directory(path, error);
    if (!error && directory) {
        vm.set_directory_probe_path(text + "\\");
    }
    thread.stack.push(!error && directory ? 1U : 0U);
    return NativeSignal::Continue;
}
